const localeTags: Record<Locale,string> = {en:"en-GB",de:"de-DE",fr:"fr-FR",es:"es-ES",it:"it-IT",nl:"nl-NL"};

export function hostDictionary(locale: Locale) {
  return (source: string) => locale === "en" ? source : translations[locale][source] ?? source;
}

export function formatHostDate(value: string, locale: Locale) {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
  if (!match) return value;
  return new Intl.DateTimeFormat(localeTags[locale],{day:"numeric",month:"short",year:"numeric",timeZone:"UTC"}).format(new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3]))));
}

export function formatHostStatus(value: string | null | undefined, locale: Locale) {
  if (!value) return "—";
  const source = value.replace(/_/g," ").replace(/^./,c=>c.toUpperCase());
  return hostDictionary(locale)(source);
}

export function formatHostCurrency(amountMinor: number | string | null | undefined, currency: string | null | undefined, locale: Locale) {
  if (amountMinor == null || !currency) return "—";
  try { return new Intl.NumberFormat(localeTags[locale],{style:"currency",currency}).format(Number(amountMinor)/100); }
  catch { return `${(Number(amountMinor)/100).toFixed(2)} ${currency}`; }
}
